CREATE OR REPLACE FUNCTION private.phase10_special_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  failed text := '';
  counts jsonb;
  model jsonb;
  hidden_id uuid;
  public_id uuid;
  hidden_card jsonb;
  public_card jsonb;
  src text;
  chance numeric;
  marker text := 'QA_CLOSURE_HIDDEN_KARPFISH';
  payload jsonb;
  trainer uuid;
  admin_uid uuid;
  tick jsonb;
  dex_n int;
  src_try text;
  launched boolean;
  live_n int;
  pub_n int;
begin
  counts := private.kanto_availability_json()->'counts';
  model := private.kanto_availability_json()->'acquisitionModel';
  if coalesce((counts->>'normal')::int, 0) <> 146 then failed := failed || format('normal=%s; ', counts->>'normal'); end if;
  if coalesce((counts->>'special')::int, 0) <> 5 then failed := failed || format('special=%s; ', counts->>'special'); end if;
  if coalesce((counts->>'evolutionOnly')::int, 0) <> 0 then failed := failed || 'evo-only; '; end if;
  if coalesce((counts->>'unavailable')::int, 0) <> 0 then failed := failed || 'unavail; '; end if;
  if coalesce((model->>'ordinaryEncounterEligible')::int, 0) <> 146 then failed := failed || 'model ordinary; '; end if;
  if coalesce((model->>'specialEventOnly')::int, 0) <> 5 then failed := failed || 'model special; '; end if;
  if coalesce((model->>'evolutionRequiredFor151')::boolean, true) is not false then failed := failed || 'evo required; '; end if;

  chance := private.capture_base_chance(3);
  if chance is distinct from 0.04 then failed := failed || format('cr3=%s; ', chance); end if;

  if private.spawn_band(144) is distinct from 'LEGENDARY' then failed := failed || 'articuno band; '; end if;
  if private.spawn_band(145) is distinct from 'LEGENDARY' then failed := failed || 'zapdos band; '; end if;
  if private.spawn_band(146) is distinct from 'LEGENDARY' then failed := failed || 'moltres band; '; end if;
  if private.spawn_band(150) is distinct from 'LEGENDARY' then failed := failed || 'mewtwo band; '; end if;
  if private.spawn_band(151) is distinct from 'LEGENDARY' then failed := failed || 'mew band; '; end if;

  if private.spawn_species_eligible(144, false)
     or private.spawn_species_eligible(145, false)
     or private.spawn_species_eligible(146, false)
     or private.spawn_species_eligible(150, false)
     or private.spawn_species_eligible(151, false) then
    failed := failed || 'eligible_auto; ';
  end if;

  src := pg_get_functiondef('private.spawn_allow_special()'::regprocedure);
  if src ilike '%stream_mode%' or src ilike '%mode =%' then
    failed := failed || 'spawn_allow_special backdoor; ';
  end if;

  src := pg_get_functiondef('private.launch_community_round(integer,text,boolean,text,boolean)'::regprocedure);
  if src not ilike '%specialEvent%' then failed := failed || 'launch missing specialEvent; '; end if;
  if src not ilike '%A Special Event is live%' then failed := failed || 'launch missing collision guard; '; end if;
  if src not ilike '%only appear through a Special Event%' then failed := failed || 'launch missing species guard; '; end if;

  src := pg_get_functiondef('private.director_tick()'::regprocedure);
  if src not ilike '%special_event_director_tick%' then failed := failed || 'tick unwired; '; end if;

  if has_function_privilege('anon', 'public.admin_special_event_command(text,jsonb)', 'execute') then
    failed := failed || 'anon execute command; ';
  end if;
  if has_function_privilege('anon', 'public.admin_special_event_analytics(uuid)', 'execute') then
    failed := failed || 'anon execute analytics; ';
  end if;
  if has_function_privilege('anon', 'public.admin_special_event_health()', 'execute') then
    failed := failed || 'anon execute health; ';
  end if;
  if not has_function_privilege('anon', 'public.play_special_events()', 'execute') then
    failed := failed || 'anon missing public events read; ';
  end if;

  foreach dex_n in array array[144, 145, 146, 150, 151]
  loop
    foreach src_try in array array['AUTO', 'ADMIN', 'ADMIN_SPECIFIC', 'TEST', 'QUEUED_SPECIAL']
    loop
      launched := false;
      begin
        perform private.launch_community_round(dex_n, null, false, src_try, false);
        launched := true;
        raise exception 'phase10_closure_rollback';
      exception
        when others then
          if sqlerrm = 'phase10_closure_rollback' or launched then
            failed := failed || format('%s %s launched; ', dex_n, src_try);
          elsif sqlerrm not ilike '%only appear through a Special Event%' then
            failed := failed || format('%s %s: %s; ', dex_n, src_try, sqlerrm);
          end if;
      end;
    end loop;

    launched := false;
    begin
      perform set_config('play.special_event_id', gen_random_uuid()::text, true);
      perform set_config('play.special_event_json', '{"id":"closure"}', true);
      perform private.launch_community_round(dex_n, null, false, 'SPECIAL_EVENT', true);
      launched := true;
      raise exception 'phase10_closure_rollback';
    exception
      when others then
        if sqlerrm = 'phase10_closure_rollback' and launched then
          null;
        else
          failed := failed || format('special %s: %s; ', dex_n, sqlerrm);
        end if;
    end;
    perform set_config('play.special_event_id', '', true);
    perform set_config('play.special_event_json', '', true);
  end loop;

  select p.id into trainer
    from public.profiles p
   where private.play_staff_role(p.id) is null
   limit 1;

  if trainer is not null then
    perform set_config('request.jwt.claim.sub', trainer::text, true);
    perform set_config('request.jwt.claim.role', 'authenticated', true);
    perform set_config('request.jwt.claims', json_build_object('sub', trainer::text, 'role', 'authenticated', 'aud', 'authenticated')::text, true);
    if private.is_play_admin() then
      failed := failed || 'trainer jwt still admin; ';
    end if;
    foreach src_try in array array['create', 'schedule', 'start_now', 'repeat', 'cancel', 'end']
    loop
      begin
        perform public.admin_special_event_command(src_try, jsonb_build_object('dex', 129, 'confirm', true, 'title', marker));
        raise exception 'phase10_trainer_allowed';
      exception
        when others then
          if sqlerrm = 'phase10_trainer_allowed' then
            failed := failed || format('trainer %s allowed; ', src_try);
          elsif sqlerrm not ilike '%not allowed%' then
            failed := failed || format('trainer %s: %s; ', src_try, sqlerrm);
          end if;
      end;
    end loop;
  else
    failed := failed || 'no trainer for rpc audit; ';
  end if;

  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', '{}', true);

  begin
    insert into private.special_events (event_type, dex, title, subtitle, visibility, status, encounter_count)
    values ('MYTHICAL', 151, 'QA HIDDEN MEW', 'Mew', 'HIDDEN', 'SCHEDULED', 1)
    returning id into hidden_id;
    hidden_card := private.special_event_public_card((select s from private.special_events s where s.id = hidden_id), false);
    if hidden_card is not null then raise exception 'hidden leaked'; end if;
    if coalesce(hidden_card->>'name', '') ilike '%mew%' then raise exception 'hidden mew name'; end if;

    insert into private.special_events (event_type, dex, title, subtitle, visibility, status, encounter_count, starts_at)
    values ('LEGENDARY', 144, 'THE FROZEN LEGEND AWAKENS', 'Articuno', 'PUBLIC', 'SCHEDULED', 3, now() + interval '7 days')
    returning id into public_id;
    public_card := private.special_event_public_card((select s from private.special_events s where s.id = public_id), false);
    if public_card is null then raise exception 'public missing'; end if;
    if coalesce(public_card->>'name', '') not ilike '%articuno%' then raise exception 'public name'; end if;
    raise exception 'phase10_closure_rollback';
  exception
    when others then
      if sqlerrm not in ('phase10_closure_rollback') then
        failed := failed || sqlerrm || '; ';
      end if;
  end;

  begin
    insert into private.special_events (
      event_type, dex, title, subtitle, announcement, visibility, status, encounter_count, starts_at
    ) values (
      'ADMIN_TEST', 129, marker, 'Magikarp', marker, 'HIDDEN', 'SCHEDULED', 1, now() + interval '7 days'
    ) returning id into hidden_id;

    payload := public.play_special_events();
    if payload::text ilike '%' || marker || '%' then raise exception 'upcoming leaked'; end if;
    payload := public.play_state();
    if payload::text ilike '%' || marker || '%' then raise exception 'play_state leaked'; end if;
    begin
      payload := public.play_pokedex('SoraStarlight');
      if payload::text ilike '%' || marker || '%' then raise exception 'pokedex leaked'; end if;
    exception
      when others then
        if sqlerrm not ilike '%sign in%' and sqlerrm not ilike '%pokedex leaked%' then
          raise exception 'pokedex: %', sqlerrm;
        elsif sqlerrm ilike '%pokedex leaked%' then
          raise;
        end if;
    end;
    payload := public.play_rankings('level', 20, 0);
    if payload::text ilike '%' || marker || '%' then raise exception 'rankings leaked'; end if;
    payload := public.play_trainer('SoraStarlight');
    if payload::text ilike '%' || marker || '%' then raise exception 'trainer leaked'; end if;
    payload := public.play_store();
    if payload::text ilike '%' || marker || '%' then raise exception 'store leaked'; end if;
    if exists (
      select 1 from pg_publication_tables
      where tablename in ('special_events', 'special_event_rounds')
    ) then
      raise exception 'realtime publication';
    end if;

    hidden_card := private.special_event_admin_json((select s from private.special_events s where s.id = hidden_id));
    if hidden_card is null or coalesce(hidden_card->>'title', '') <> marker then
      raise exception 'admin missing hidden';
    end if;

    update private.special_events
       set rounds_launched = 1, status = 'LIVE', updated_at = now()
     where id = hidden_id;
    public_card := private.special_event_public_card((select s from private.special_events s where s.id = hidden_id), false);
    if public_card is null then raise exception 'reveal missing public card'; end if;
    if coalesce(public_card->>'title', '') <> marker then raise exception 'reveal title'; end if;
    raise exception 'phase10_closure_rollback';
  exception
    when others then
      if sqlerrm not in ('phase10_closure_rollback') then
        failed := failed || 'hidden-leak: ' || sqlerrm || '; ';
      end if;
  end;

  begin
    insert into private.special_events (event_type, dex, title, visibility, status, encounter_count)
    values ('ADMIN_TEST', 129, marker || '_LIVE', 'HIDDEN', 'LIVE', 1)
    returning id into hidden_id;
    begin
      insert into private.special_events (event_type, dex, title, visibility, status, encounter_count)
      values ('ADMIN_TEST', 129, marker || '_LIVE2', 'HIDDEN', 'LIVE', 1);
      raise exception 'second live allowed';
    exception
      when unique_violation then
        null;
      when others then
        if sqlerrm ilike '%second live allowed%' then
          raise;
        elsif sqlerrm ilike '%special_events_one_live%' or sqlerrm ilike '%unique%' then
          null;
        else
          raise;
        end if;
    end;

    begin
      perform private.launch_community_round(25, null, false, 'AUTO', false);
      raise exception 'auto overwrote live';
    exception
      when others then
        if sqlerrm not ilike '%Special Event is live%' then
          raise exception 'auto: %', sqlerrm;
        end if;
    end;

    begin
      perform private.launch_community_round(25, null, false, 'ADMIN', false);
      raise exception 'manual overwrote live';
    exception
      when others then
        if sqlerrm not ilike '%Special Event is live%' then
          raise exception 'manual: %', sqlerrm;
        end if;
    end;

    begin
      perform private.special_event_start_round(hidden_id);
      perform private.special_event_start_round(hidden_id);
      raise exception 'duplicate special start';
    exception
      when others then
        if sqlerrm ilike '%duplicate special start%' then
          raise;
        elsif sqlerrm ilike '%already%' or sqlerrm ilike '%This event round already started%' then
          null;
        else
          raise;
        end if;
    end;
    raise exception 'phase10_closure_rollback';
  exception
    when others then
      if sqlerrm not in ('phase10_closure_rollback') then
        failed := failed || 'collision: ' || sqlerrm || '; ';
      end if;
  end;

  begin
    insert into private.special_events (
      event_type, dex, title, visibility, status, encounter_count, starts_at, auto_advance
    ) values (
      'ADMIN_TEST', 129, marker || '_WAIT', 'HIDDEN', 'SCHEDULED', 1, now() - interval '1 minute', true
    ) returning id into hidden_id;
    tick := private.special_event_director_tick(false);
    if coalesce(tick->>'status', '') is distinct from 'WAITING_FOR_STREAM' then
      raise exception 'offline tick %', tick;
    end if;
    select status into src_try from private.special_events where id = hidden_id;
    if src_try is distinct from 'WAITING_FOR_STREAM' then
      raise exception 'offline consumed as %', src_try;
    end if;
    if exists (
      select 1 from private.special_event_rounds where event_id = hidden_id
    ) then
      raise exception 'offline launched round';
    end if;
    tick := private.special_event_director_tick(false);
    select status into src_try from private.special_events where id = hidden_id;
    if src_try is distinct from 'WAITING_FOR_STREAM' then
      raise exception 'reload lost wait %', src_try;
    end if;
    raise exception 'phase10_closure_rollback';
  exception
    when others then
      if sqlerrm not in ('phase10_closure_rollback') then
        failed := failed || 'offline: ' || sqlerrm || '; ';
      end if;
  end;

  if exists (
    select 1 from private.store_items
    where status = 'published'
      and (
        grants ? 'articuno' or grants ? 'mew' or grants ? 'mewtwo'
        or coalesce(grants->>'legendary', '') <> ''
      )
  ) then failed := failed || 'paid legendary sku; '; end if;

  select count(*)::int into live_n from private.special_events where title ilike marker || '%';
  if live_n > 0 then failed := failed || format('leftover qa events=%s; ', live_n); end if;
  select count(*)::int into pub_n
    from public.encounter_rounds
   where last_action ilike '%QA_CLOSURE%' or (rules->'specialEvent'->>'title') ilike '%' || marker || '%';
  if pub_n > 0 then failed := failed || format('leftover qa rounds=%s; ', pub_n); end if;

  if failed <> '' then
    return jsonb_build_object('ok', false, 'failed', failed);
  end if;
  return jsonb_build_object('ok', true, 'counts', counts, 'acquisitionModel', model);
end;
$function$

CREATE OR REPLACE FUNCTION private.phase6_rankings_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  payload jsonb;
  honey jsonb;
  pokedex jsonb;
  search_email jsonb;
  search_name jsonb;
  src text;
  trainer jsonb;
  honey_metric int;
  honey_stat int;
  honey_inv int;
  kanto_metric int;
  kanto_true int;
  sora uuid := '60ff5211-6ef8-40e6-8daa-095b5600bf4c';
  tester uuid := 'a98cbf81-a6b2-4dbf-8448-8d62f6d5f523';
  over_featured int;
  failed text := '';
begin
  payload := public.play_rankings('level', 20, 0);
  pokedex := public.play_rankings('pokedex', 20, 0);
  honey := public.play_rankings('honey', 20, 0);
  search_email := public.play_trainer_search('qa@example.com');
  search_name := public.play_trainer_search('Sora');
  src := pg_get_functiondef('public.play_rankings(text,integer,integer)'::regprocedure);

  if coalesce(payload->>'ok', '') <> 'true' then failed := failed || 'rankings not ok; '; end if;
  if payload::text ~* 'userKey|"email"|access_token' then failed := failed || 'private fields in rankings; '; end if;
  if exists (
    select 1 from jsonb_array_elements(payload->'trainers') t
    where t->>'displayName' = 'Play Tester' or t->>'login' = 'playtester'
  ) then failed := failed || 'Play Tester on public board; '; end if;
  if private.ranking_eligible_uid(tester) then failed := failed || 'tester still eligible; '; end if;
  if not private.ranking_eligible_uid(sora) then failed := failed || 'Sora not eligible; '; end if;
  if coalesce(pokedex->>'definition', '') not ilike '%Kanto%' then failed := failed || 'pokedex definition; '; end if;
  if coalesce(honey->>'definition', '') not ilike '%contributed%' then failed := failed || 'honey definition; '; end if;
  if src not ilike '%rank()%' then failed := failed || 'ties not rank(); '; end if;
  if src ilike '%inventories.bait%' then failed := failed || 'honey used inventory; '; end if;
  if src ilike '%POWER SCORE%' or src ilike '%OVERALL RANK%' or src ilike '%TRAINER RATING%' then
    failed := failed || 'composite score; ';
  end if;
  if jsonb_array_length(coalesce(search_email->'trainers', '[]'::jsonb)) <> 0 then
    failed := failed || 'email search leaked; ';
  end if;
  if jsonb_array_length(coalesce(search_name->'trainers', '[]'::jsonb)) < 1 then
    failed := failed || 'name search missed; ';
  end if;

  select (t.elem->>'metric')::int
    into honey_metric
    from jsonb_array_elements(honey->'trainers') t(elem)
    join public.profiles p on coalesce(nullif(p.twitch_login, ''), nullif(p.username, '')) = t.elem->>'login'
   where p.id = sora
   limit 1;
  select coalesce(s.honey, 0), coalesce(i.bait, 0)
    into honey_stat, honey_inv
    from public.profiles p
    left join public.trainer_stats s on s.user_id = p.id
    left join public.inventories i on i.user_id = p.id
   where p.id = sora;
  if honey_metric is not null and honey_metric is distinct from honey_stat then
    failed := failed || 'honey metric != trainer_stats.honey; ';
  end if;
  if honey_stat = honey_inv and honey_inv > 20 then
    failed := failed || 'honey looks like inventory; ';
  end if;

  select (t.elem->>'metric')::int
    into kanto_metric
    from jsonb_array_elements(pokedex->'trainers') t(elem)
    join public.profiles p on coalesce(nullif(p.twitch_login, ''), nullif(p.username, '')) = t.elem->>'login'
   where p.id = sora
   limit 1;
  select count(distinct dex)::int into kanto_true
    from public.catches where user_id = sora and dex between 1 and 151;
  if kanto_metric is not null and kanto_metric is distinct from kanto_true then
    failed := failed || 'pokedex not unique Kanto; ';
  end if;

  select count(*)::int into over_featured
    from public.profiles
   where coalesce(cardinality(featured_badge_ids), 0) > 3;
  if over_featured > 0 then failed := failed || 'featured badges > 3; '; end if;
  if pg_get_functiondef('public.play_set_badges(text[])'::regprocedure) not ilike '%limit 3%' then
    failed := failed || 'badge cap missing; ';
  end if;

  select value from jsonb_array_elements(payload->'trainers') into trainer limit 1;
  if trainer is not null and (trainer ? 'email' or trainer ? 'userKey' or trainer ? 'pass' or trainer ? 'watchSeconds') then
    failed := failed || 'row leaked private keys; ';
  end if;

  if failed <> '' then
    return jsonb_build_object('ok', false, 'failed', failed, 'payloadBoard', payload->>'board');
  end if;
  return jsonb_build_object('ok', true, 'eligible', payload->'eligible', 'levelRows', jsonb_array_length(payload->'trainers'));
end;
$function$

CREATE OR REPLACE FUNCTION private.phase7_content_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cases jsonb := '[]'::jsonb;
  idn jsonb;
  q jsonb;
  t jsonb;
begin
  idn := private.item_identity('netball');
  cases := cases || jsonb_build_array(jsonb_build_object('name','netball-identity','ok', (idn->>'condition') = 'TARGET_TYPE'));
  idn := private.item_identity('quickball');
  cases := cases || jsonb_build_array(jsonb_build_object('name','quickball-early','ok', (idn->>'condition') = 'THROW_EARLY'));
  idn := private.item_identity('dreamball');
  cases := cases || jsonb_build_array(jsonb_build_object('name','dreamball-collector','ok', coalesce((idn->>'collector')::boolean,false)));
  idn := private.item_identity('bait');
  cases := cases || jsonb_build_array(jsonb_build_object('name','honey-community','ok', (idn->>'condition') = 'COMMUNITY_HONEY'));
  q := private.capture_ball_modifier('quickball', 16, false, now(), private.capture_config() || jsonb_build_object('_context', jsonb_build_object('throwProgress', 0.1)));
  t := private.capture_ball_modifier('quickball', 16, false, now(), private.capture_config() || jsonb_build_object('_context', jsonb_build_object('throwProgress', 0.9)));
  cases := cases || jsonb_build_array(jsonb_build_object('name','quick-early-vs-late','ok', coalesce((q->>'conditionMet')::boolean,false) and not coalesce((t->>'conditionMet')::boolean,false)));
  q := private.capture_ball_modifier('loveball', 25, false, now(), private.capture_config() || jsonb_build_object('_context', jsonb_build_object('gender','Female')));
  t := private.capture_ball_modifier('loveball', 144, false, now(), private.capture_config() || jsonb_build_object('_context', jsonb_build_object('gender','Genderless')));
  cases := cases || jsonb_build_array(jsonb_build_object('name','love-gendered','ok', coalesce((q->>'conditionMet')::boolean,false) and not coalesce((t->>'conditionMet')::boolean,false)));
  q := private.capture_ball_modifier('levelball', 16, false, now(), private.capture_config() || jsonb_build_object('_context', jsonb_build_object('trainerLevel', 12)));
  t := private.capture_ball_modifier('levelball', 16, false, now(), private.capture_config() || jsonb_build_object('_context', jsonb_build_object('trainerLevel', 3)));
  cases := cases || jsonb_build_array(jsonb_build_object('name','level-trainer','ok', coalesce((q->>'conditionMet')::boolean,false) and not coalesce((t->>'conditionMet')::boolean,false)));
  begin
    perform private.validate_store_grants('{"odds":0.5,"pokeball":1}'::jsonb);
    cases := cases || jsonb_build_array(jsonb_build_object('name','no-lootbox','ok', false));
  exception when others then
    cases := cases || jsonb_build_array(jsonb_build_object('name','no-lootbox','ok', sqlerrm ilike '%random%'));
  end;
  begin
    perform private.validate_store_grants('{"masterball":1}'::jsonb);
    cases := cases || jsonb_build_array(jsonb_build_object('name','no-master-pack','ok', false));
  exception when others then
    cases := cases || jsonb_build_array(jsonb_build_object('name','no-master-pack','ok', sqlerrm ilike '%Master Ball%'));
  end;
  cases := cases || jsonb_build_array(jsonb_build_object('name','draft-hidden', 'ok', not exists (select 1 from private.store_items i where i.status='draft' and private.store_item_is_live(i))));
  return jsonb_build_object('ok', not exists (select 1 from jsonb_array_elements(cases) x where coalesce((x->>'ok')::boolean,false) is not true), 'cases', cases);
end;$function$

CREATE OR REPLACE FUNCTION private.phase8_bits_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  failed text := '';
  eid text;
  r jsonb;
  r2 jsonb;
  can_anon boolean;
  can_auth boolean;
  live_sku text;
  live_bits int;
  live_title text;
begin
  begin
    perform private.bits_validate_grants('{"odds":1,"pokeball":1}'::jsonb);
    failed := failed || 'odds allowed; ';
  exception when others then null;
  end;
  begin
    perform private.bits_validate_grants('{"masterball":1}'::jsonb);
    failed := failed || 'masterball allowed; ';
  exception when others then null;
  end;
  begin
    perform private.bits_validate_grants('{"shiny":1}'::jsonb);
    failed := failed || 'shiny allowed; ';
  exception when others then null;
  end;
  begin
    perform private.validate_store_grants('{"masterball":1}'::jsonb);
    failed := failed || 'validate masterball; ';
  exception when others then null;
  end;

  select p.sku, p.bits, coalesce(p.titles->>0, lower(p.name)) into live_sku, live_bits, live_title
  from private.bits_live_products() p
  order by p.bits
  limit 1;
  if live_sku is null then failed := failed || 'no live bits product; '; end if;

  eid := 'qa-self:' || replace(gen_random_uuid()::text, '-', '');
  r := public.credit_bits_from_twitch(eid, 'qa-phase8-unlinked', coalesce(live_title, 'starter pack'), coalesce(live_bits, 100), null);
  if coalesce(r->>'status', '') not in ('pending', 'unresolved') then
    failed := failed || 'unlinked not pending; ';
  end if;
  if not exists (select 1 from private.bits_pending where event_id = eid) then
    failed := failed || 'unlinked not queued; ';
  end if;
  r2 := public.credit_bits_from_twitch(eid, 'qa-phase8-unlinked', coalesce(live_title, 'starter pack'), coalesce(live_bits, 100), null);
  if coalesce(r2->>'duplicate', '') <> 'true' then
    failed := failed || 'duplicate not blocked; ';
  end if;

  eid := 'qa-self:' || replace(gen_random_uuid()::text, '-', '');
  r := public.credit_bits_from_twitch(eid, 'qa-phase8-general', 'not a store product', 17, 'qa-user');
  if coalesce(r->>'general', '') <> 'true' and coalesce(r->>'status', '') <> 'ignored' then
    failed := failed || 'unmatched not ignored; ';
  end if;
  if exists (select 1 from public.reward_events where idempotency = 'bits:' || eid) then
    failed := failed || 'unmatched granted; ';
  end if;

  eid := 'qa-self:' || replace(gen_random_uuid()::text, '-', '');
  r := public.credit_bits_from_twitch(eid, '', coalesce(live_title, 'starter pack'), coalesce(live_bits, 100), '');
  if coalesce(r->>'status', '') <> 'unresolved' then failed := failed || 'anonymous not unresolved; '; end if;
  delete from private.bits_pending where event_id = eid;
  delete from private.bits_events where event_id = eid;

  select has_function_privilege('anon', 'public.credit_bits_from_twitch(text,text,text,int,text)', 'execute') into can_anon;
  select has_function_privilege('authenticated', 'public.credit_bits_from_twitch(text,text,text,int,text)', 'execute') into can_auth;
  if can_anon or can_auth then failed := failed || 'browser can credit bits; '; end if;

  if exists (select 1 from private.bits_live_products() p where p.sku in ('bits-community', 'bits-evo')) then
    failed := failed || 'draft packs are live; ';
  end if;
  if private.bits_sku('starlight community pack', 175) is not null then
    failed := failed || 'draft title matched live; ';
  end if;

  delete from private.bits_pending where event_id like 'qa-self:%';
  delete from private.bits_events where event_id like 'qa-self:%';

  if failed <> '' then
    return jsonb_build_object('ok', false, 'failed', failed);
  end if;
  return jsonb_build_object('ok', true, 'liveProduct', live_sku, 'draftsHidden', true);
end;
$function$

CREATE OR REPLACE FUNCTION private.phase9_balance_selftest()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  failed text := '';
  chance numeric;
  pinap numeric;
  silver numeric;
  src text;
  live_master int;
  live_beast int;
  ultra_grants jsonb;
  pouch_grants jsonb;
  cap int;
begin
  chance := private.capture_base_chance(45);
  if chance is distinct from 0.16 then failed := failed || format('cr45=%s; ', chance); end if;
  chance := private.capture_base_chance(25);
  if chance is distinct from 0.11 then failed := failed || format('cr25=%s; ', chance); end if;
  chance := private.capture_base_chance(3);
  if chance is distinct from 0.04 then failed := failed || format('cr3=%s; ', chance); end if;

  select reward_bonus into pinap from public.capture_berries where key = 'pinap';
  select reward_bonus into silver from public.capture_berries where key = 'silverpinap';
  if coalesce(pinap, 0) <> 2 then failed := failed || format('pinap=%s; ', pinap); end if;
  if coalesce(silver, 0) <> 1.5 then failed := failed || format('silver=%s; ', silver); end if;

  src := pg_get_functiondef('private.settle_if_needed(public.encounter_rounds)'::regprocedure);
  if src not ilike '%capture_throw_context%' then failed := failed || 'throw context unwired; '; end if;

  select count(*)::int into live_master from private.store_items where sku = 'master1' and status = 'published';
  if live_master > 0 then failed := failed || 'masterball live; '; end if;
  select count(*)::int into live_beast from private.store_items where sku = 'beast1' and status = 'published';
  if live_beast > 0 then failed := failed || 'beastball live; '; end if;

  select grants into ultra_grants from private.store_items where sku = 'bits-ultra';
  if coalesce((ultra_grants->>'ultraball')::int, 0) > 2 then failed := failed || 'ultra pack still stacked; '; end if;
  if ultra_grants ? 'bag_bonus' then failed := failed || 'ultra bag_bonus; '; end if;
  select grants into pouch_grants from private.store_items where sku = 'bits-pouch';
  if pouch_grants ? 'bag_bonus' then failed := failed || 'explorer still bag-only; '; end if;
  if coalesce((pouch_grants->>'pokeball')::int, 0) < 1 then failed := failed || 'explorer empty; '; end if;

  cap := private.bag_bonus_cap();
  if cap <> 100 then failed := failed || format('bag cap %s; ', cap); end if;

  if (private.economy_config()->'dailySupply'->>'coins')::int <> 40 then
    failed := failed || 'daily coins; ';
  end if;

  if exists (select 1 from private.store_items where sku = 'bits-community' and status is distinct from 'published') then failed := failed || 'community not published; '; end if;
  if exists (select 1 from private.store_items where sku = 'bits-evo' and status = 'published') then failed := failed || 'evo pack live; '; end if;

  if failed <> '' then
    return jsonb_build_object('ok', false, 'failed', failed);
  end if;
  return jsonb_build_object('ok', true, 'pinap', pinap, 'bagBonusCap', cap);
end;
$function$
